function escapeCsvCell(value) {
  const str = String(value ?? '');
  // Prefix with tab to prevent formula injection
  if (/^[=+@\-]/.test(str)) return "'" + str;
  // Quote if contains comma, double quote, or newline
  if (/[,"\n\r]/.test(str)) {
    return '"' + str.replace(/"/g, '""') + '"';
  }
  return str;
}

