/**
 * Parse a single CSV line with RFC4180-style quoted fields.
 * NOTE: This function does NOT handle multi-line quoted fields.
 * Callers must ensure the input is a complete logical line.
 */
export function parseCsvLine(line) {
  if (line == null) return [];
  const out = [];
  let cur = '';
  let inQuotes = false;
  const s = String(line);
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (inQuotes) {
      if (c === '"') {
        if (s[i + 1] === '"') {
          cur += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        cur += c;
      }
    } else if (c === '"') {
      inQuotes = true;
    } else if (c === ',') {
      out.push(cur.trim());
      cur = '';
    } else {
      cur += c;
    }
  }
  out.push(cur.trim());
  return out;
}

